CREATE TABLE bean_wallets (id VARCHAR(191) PRIMARY KEY, owner_key VARCHAR(191) NOT NULL UNIQUE, status VARCHAR(20) NOT NULL DEFAULT 'active', created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE bean_accounts (id VARCHAR(191) PRIMARY KEY,wallet_id VARCHAR(191) NOT NULL,bucket VARCHAR(40) NOT NULL,balance BIGINT NOT NULL DEFAULT 0,version INT NOT NULL DEFAULT 0,UNIQUE KEY bean_accounts_wallet_id_bucket_key(wallet_id,bucket),FOREIGN KEY(wallet_id) REFERENCES bean_wallets(id));
CREATE TABLE bean_movements (id VARCHAR(191) PRIMARY KEY,request_key VARCHAR(191) NOT NULL UNIQUE,fingerprint CHAR(64) NOT NULL,kind VARCHAR(40) NOT NULL,reason VARCHAR(500) NOT NULL,actor_id VARCHAR(191) NOT NULL,reference_id VARCHAR(191) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX bean_movements_kind_created_at_idx(kind,created_at));
CREATE TABLE bean_entries (id VARCHAR(191) PRIMARY KEY,movement_id VARCHAR(191) NOT NULL,account_id VARCHAR(191) NOT NULL,delta BIGINT NOT NULL,balance_after BIGINT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY bean_entries_movement_id_account_id_key(movement_id,account_id),INDEX bean_entries_account_id_created_at_idx(account_id,created_at),FOREIGN KEY(movement_id) REFERENCES bean_movements(id),FOREIGN KEY(account_id) REFERENCES bean_accounts(id));
INSERT INTO bean_wallets(id,owner_key) VALUES ('bean-company','company'),('bean-issuance','issuance');
INSERT INTO bean_accounts(id,wallet_id,bucket,balance) VALUES ('bean-stock','bean-company','stock',100000000),('bean-issued','bean-issuance','issued',-100000000);
