INSERT INTO bean_entries(id,movement_id,account_id,delta,balance_after) VALUES ('bean-genesis-stock','bean-genesis','bean-stock',100000000,100000000),('bean-genesis-issued','bean-genesis','bean-issued',-100000000,-100000000);
